SoilSensor soil(A0, 520, 260);
CsvLog logger("seconds,soil_percent,raw");
Every check(2000);

void setup() {
  logger.begin(9600);
}

void loop() {
  if (!check.ready()) return;
  logger.row(millis() / 1000, soil.percent(), soil.raw());
}

Relay pump(7, true, 60000UL);   // pin 7, switches on LOW, never more than 60 s

void setup() {
  logger.begin(9600);
  pump.begin();
  pump.runFor(3000);   // test: 3 seconds, remove later
}

